function applyTheme(){const h=document.documentElement;h.dataset.theme=theme;h.dataset.mode=mode;try{localStorage.setItem("mtpfms-theme2",JSON.stringify({theme,mode}))}catch(e){}}
function setTheme(t,m){if(t)theme=t;if(m)mode=m;applyTheme();renderCust()}
function renderCust(){document.getElementById("cust").innerHTML=`<div class="dh"><h2>Customization</h2><button class="btn alt" onclick="closeCust()" aria-label="Close">✕</button></div><div class="db"><h3>Mode</h3><div class="tools"><button class="btn ${mode=="light"?"":"alt"}" onclick="setTheme(null,'light')">Light</button><button class="btn ${mode=="dark"?"":"alt"}" onclick="setTheme(null,'dark')">Dark</button></div>
<h3>Theme</h3><p class="hint" style="margin-top:0">Applies to every page and is saved in this browser.</p>
<div class="thms">${TH.map(([id,n])=>`<button class="thm ${id==theme?"on":""}" onclick="setTheme('${id}')"><span class="sw" data-theme="${id}" data-mode="${mode}"><i style="background:var(--primary)"></i><i style="background:var(--secondary)"></i><i style="background:var(--sidebar-background)"></i><i style="background:var(--surface)"></i></span><b>${n}</b><small>${id==theme?"✓ Selected":"Click to apply"}</small></button>`).join("")}</div></div>`}
function openCust(){const d=document.getElementById("cust");if(d.classList.contains("open"))return closeCust();renderCust();d.classList.add("open");document.getElementById("cbk").classList.add("open")}
function closeCust(){document.getElementById("cust").classList.remove("open");document.getElementById("cbk").classList.remove("open")}
document.addEventListener("keydown",e=>{if(e.key=="Escape")closeCust()});
function logs(){return `<h2>Activity Logs</h2><div class="tw"><table class="rt"><tr><th>Time</th><th>Role</th><th>Action</th></tr>${log.map(l=>`<tr><td data-label="Time">${l[0]}</td><td data-label="Role">${l[1]}</td><td data-label="Action" style="white-space:normal">${esc(l[2])}</td></tr>`).join("")||"<tr><td colspan=3>No activity yet. Add or edit a record to see entries.</td></tr>"}</table></div>`}
function L(a){log.unshift([new Date().toLocaleString(),role,a]);if(!/^(Viewed|Printed|Exported) /.test(a))chg++;persist()}
function closeModal(){camStop();shot=null;editId=null;PA=null;imp=null;document.getElementById("modal").innerHTML=""}
function pa(id,t){PA=t?{id,t}:null;prof(id)}
