function doRenew(id){const r=data.find(x=>x.id==id);if(!r||!isAdm())return;if(r.status=="Suspended"||r.status=="Cancelled")return toast("Set the status to Active first (Edit), then renew.");
const to=g$("ry").value+"-12-31";if(to<=r.exp)return toast("The new expiry must be later than "+r.exp+".");r.hist=r.hist||[];r.hist.unshift({at:iso(0),from:r.exp,to,role});const from=r.exp;r.exp=to;r.status="Active";L("Renewed "+r.name+": expiry "+from+" → "+to);PA=null;draw();prof(id);toast("Renewed until "+to)}
function doArchive(id){const r=data.find(x=>x.id==id);if(role!="super_admin"||!r)return;if(D().some(d=>d.asg==id))return toast("Archive or reassign this operator's drivers first.");r.arch=iso(0);L("Archived "+r.name);closeModal();draw();toast("Archived "+r.name)}
function doRestore(id){const r=data.find(x=>x.id==id);if(role!="super_admin"||!r)return;r.arch=null;L("Restored "+r.name);draw();prof(id);toast("Restored "+r.name)}
function photo(id,el){const f=el.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{data.find(x=>x.id==id).photo=rd.result;L("Photo updated #"+id);prof(id)};rd.readAsDataURL(f)}
let shot=null,strm=null;
