function dqData(){const rows=D(),miss=[],groups=[],v=x=>String(x||"").trim().toLowerCase(),ops=rows.filter(r=>r.cls!="Driver");
rows.forEach(r=>{const m=[];if(r.cls!="Driver"&&!v(r.plate))m.push("Plate");if(!r.photo)m.push("Photo");if(!v(r.phone))m.push("Contact");if(m.length)miss.push([r,m])});
const nk=r=>String(r.name).toLowerCase().replace(/\(sample\)/g,"").replace(/[^\p{L}\p{N} ]/gu," ").split(/\s+/).filter(Boolean).sort().join(" ");
const grp=(label,key,list,show)=>{const m={};list.forEach(r=>{const k=key(r);if(k)(m[k]=m[k]||[]).push(r)});Object.values(m).filter(g=>g.length>1).forEach(g=>groups.push([label,show(g[0]),g]))};
grp("Same name and barangay",r=>nk(r)&&nk(r)+"|"+r.brgy,rows,g=>g[0].name+" · "+g[0].brgy);
[["Plate number","plate"],["MTOP No.","mtop"],["OR No.","or"],["Chassis No.","chassis"]].forEach(([l,k])=>grp(l,r=>v(r[k]),ops,g=>g[0][k]));
return{miss,groups}}
function dq(){if(!isAdm())return `<h2>Data Quality</h2><p>Available to administrators only.</p>`;
const{miss,groups}=dqData(),f=flt.dq||"",cnt=k=>miss.filter(x=>x[1].includes(k)).length,list=miss.filter(x=>!f||x[1].includes(f)),cap=300,
cell=(r,m,k)=>k=="Plate"&&r.cls=="Driver"?"n/a":m.includes(k)?"<b>Missing</b>":"OK";
return `<h2>Data Quality</h2><p class="hint">Archived records are left out. Plate applies to operators only. Duplicates are matched on the same name in the same barangay (word order and punctuation ignored), or on the same plate, MTOP, OR or chassis number. Open a holder and use Edit to fix a record.</p>
<div class="cards"><div class="card"><b>${cnt("Plate")}</b>Missing plate</div><div class="card"><b>${cnt("Photo")}</b>Missing photo</div><div class="card"><b>${cnt("Contact")}</b>Missing contact no.</div><div class="card"><b>${groups.length}</b>Possible duplicate groups</div></div>
<div class="panel"><h3>Missing details (${list.length})</h3><div class="tools"><select onchange="flt.dq=this.value;draw()">${[["","Any missing detail"],["Plate","Missing plate"],["Photo","Missing photo"],["Contact","Missing contact no."]].map(o=>`<option value="${o[0]}" ${o[0]==f?"selected":""}>${o[1]}</option>`).join("")}</select><button class="btn alt" onclick="dqCsv('miss')">Export CSV</button></div>
<div class="tw"><table class="rt"><tr><th>Holder</th><th>Type</th><th>Association</th><th>Barangay</th><th>Plate</th><th>Photo</th><th>Contact no.</th></tr>${list.slice(0,cap).map(([r,m])=>`<tr><td data-label="Holder"><a onclick="prof(${r.id})">${esc(r.name)}</a>${r.cls=="Driver"?" <small>(driver)</small>":""}</td><td data-label="Type">${r.cat}</td><td data-label="Association">${esc(r.assoc)}</td><td data-label="Barangay">${esc(r.brgy)}</td><td data-label="Plate">${cell(r,m,"Plate")}</td><td data-label="Photo">${cell(r,m,"Photo")}</td><td data-label="Contact no.">${cell(r,m,"Contact")}</td></tr>`).join("")||`<tr><td colspan="7">Nothing missing.</td></tr>`}</table></div>${list.length>cap?`<p class="hint">Showing the first ${cap} of ${list.length}. Export CSV for the full list.</p>`:""}</div>
<div class="panel"><h3>Possible duplicates (${groups.length})</h3><div class="tools"><button class="btn alt" onclick="dqCsv('dup')">Export CSV</button></div>
<div class="tw"><table class="rt"><tr><th>Matched on</th><th>Value</th><th>Holders</th></tr>${groups.slice(0,cap).map(g=>`<tr><td data-label="Matched on">${g[0]}</td><td data-label="Value">${esc(g[1])}</td><td data-label="Holders" style="white-space:normal">${g[2].map(r=>`<a onclick="prof(${r.id})">${esc(r.name)}</a> <small>(${esc(r.brgy)})</small>`).join(", ")}</td></tr>`).join("")||`<tr><td colspan="3">No possible duplicates found.</td></tr>`}</table></div>${groups.length>cap?`<p class="hint">Showing the first ${cap} of ${groups.length}.</p>`:""}</div>`}
function dqCsv(t){if(!isAdm())return;const{miss,groups}=dqData();let head,body;
if(t=="miss"){head=["Holder","Classification","Type","Association","Barangay","Missing"];body=miss.map(([r,m])=>[r.name,r.cls,r.cat,r.assoc,r.brgy,m.join("; ")])}
else{head=["Matched on","Value","Holders"];body=groups.map(g=>[g[0],g[1],g[2].map(r=>r.name+" ("+r.brgy+")").join("; ")])}
dlf("data-quality-"+t+"-"+iso(0)+".csv",[head.map(cq).join(",")].concat(body.map(r=>r.map(cq).join(","))).join("\r\n"));L("Exported data quality report ("+t+")")}

